"""
patch14_odorblock_abr26.py
Atualiza o módulo Odor Block com dados ABR/26 e corrige bugs estruturais.

Fonte: Base Giovano Odor Block (25-05).xlsx — data 2026-04-26

Fixes aplicados:
  1. OB_PERIODS: adiciona "Abr/26" (index 9)
  2. OB_DATA: adiciona index [9] em share/preco/valor/unid para todos os
     7 markets × 7 produtos
  3. renderOBMercado: hardcoded "Mar/26" no diagnóstico → OB_PERIODS[latest]
  4. syncOBMarket: nova função que sincroniza todos os 4 seletores de market
  5. Seletores HTML: onchange atualizado para usar syncOBMarket
  6. Card 3 subtitle "Farma Sul" hardcoded → adiciona id + atualização dinâmica
  7. renderOBShare: atualiza span ob-share-mkt-lbl com market selecionado
"""
import os, shutil, datetime, sys, re
sys.stdout.reconfigure(encoding='utf-8')

BASE = r"C:\Users\valqu\OneDrive\Documentos\Claude\Projects\projeto Dashboard_farma_sul\Dashboard_farma_sul"
SRC  = os.path.join(BASE, "Dashboard_Farma_Sul_20260512_2220.html")

with open(SRC, 'r', encoding='utf-8') as f:
    html = f.read()

original_len = len(html)
patches = 0

def patch(old, new, desc):
    global html, patches
    c = html.count(old)
    if c == 0:
        print(f"  [X] NAO ENCONTRADO: {desc}")
        return False
    if c > 1:
        print(f"  [!] {c}x (substituindo 1): {desc}")
    html = html.replace(old, new, 1)
    patches += 1
    print(f"  [OK] {desc}")
    return True

def patch_all(old, new, desc):
    global html, patches
    c = html.count(old)
    if c == 0:
        print(f"  [X] NAO ENCONTRADO: {desc}")
        return 0
    html = html.replace(old, new)
    patches += c
    print(f"  [OK] ({c}x) {desc}")
    return c

