# 4. Adicionar syncOBMarket() depois de initOdorBlock
# ─────────────────────────────────────────────────────────────────
print("\n--- 4. Adicionar syncOBMarket() ---")
patch(
    "function initOdorBlock(){\n"
    "  var s1=document.getElementById('obMarketSel'); if(s1) s1.value=obMarket1;\n"
    "  var s2=document.getElementById('obMarketSel2'); if(s2) s2.value=obMarket2;\n"
    "  var s3=document.getElementById('obMarketSel3'); if(s3) s3.value=obMarket3;\n"
    "  var s4=document.getElementById('obMarketSel4'); if(s4) s4.value=obMarket4;\n"
    "  renderOBShare();\n"
    "  renderOBPreco();\n"
    "  renderOBVendas();\n"
    "  renderOBMercado();\n"
    "}",
    "function initOdorBlock(){\n"
    "  var s1=document.getElementById('obMarketSel'); if(s1) s1.value=obMarket1;\n"
    "  var s2=document.getElementById('obMarketSel2'); if(s2) s2.value=obMarket2;\n"
    "  var s3=document.getElementById('obMarketSel3'); if(s3) s3.value=obMarket3;\n"
    "  var s4=document.getElementById('obMarketSel4'); if(s4) s4.value=obMarket4;\n"
    "  renderOBShare();\n"
    "  renderOBPreco();\n"
    "  renderOBVendas();\n"
    "  renderOBMercado();\n"
    "}\n"
    "/* Sincroniza todos os 4 cards OB ao trocar market */\n"
    "function syncOBMarket(val){\n"
    "  obMarket1=obMarket2=obMarket3=obMarket4=val;\n"
    "  var s1=document.getElementById('obMarketSel'); if(s1) s1.value=val;\n"
    "  var s2=document.getElementById('obMarketSel2'); if(s2) s2.value=val;\n"
    "  var s4=document.getElementById('obMarketSel4'); if(s4) s4.value=val;\n"
    "  var subEl=document.getElementById('ob-mkt-sub');\n"
    "  if(subEl){\n"
    "    var lbl=val.replace('AS+C&C+','');\n"
    "    subEl.textContent='NielsenIQ · R$ e Unidades · '+OB_PERIODS[0]+'–'+OB_PERIODS[OB_PERIODS.length-1]+' · '+lbl;\n"
    "  }\n"
    "  renderOBShare(); renderOBPreco(); renderOBVendas(); renderOBMercado();\n"
    "}",
    "Adicionar syncOBMarket() após initOdorBlock"
)

# ─────────────────────────────────────────────────────────────────
