# ─────────────────────────────────────────────────────────────────
print("\n--- 5. Selectors HTML: usar syncOBMarket ---")
patch(
    'onchange="obMarket1=this.value;renderOBShare()"',
    'onchange="syncOBMarket(this.value)"',
    "obMarketSel card1 → syncOBMarket"
)
patch(
    'onchange="obMarket2=this.value;renderOBPreco()"',
    'onchange="syncOBMarket(this.value)"',
    "obMarketSel2 card2 → syncOBMarket"
)
patch(
    'onchange="obMarket4=this.value;renderOBMercado()"',
    'onchange="syncOBMarket(this.value)"',
    "obMarketSel4 card3 → syncOBMarket"
)

